<!--
  The command card at the bottom right: abilities, orders and buildings
  as square tiles four to a row, each its picture with a lit edge, the
  hotkey in its corner, a cooldown as a dark sweep with the seconds left,
  a command that cannot be paid for greyed with its price on a red tag, a
  disabled one greyed, the order in hand lit; the info card of the
  command in focus over the grid (its name and key, what it does, its
  price, cooldown and when it is ready, or why it cannot be used).
  Reports command (the tile's key; a disabled or unaffordable tile sends
  nothing); the game owns every cost, cooldown and rule.
-->
<section id="StrategyCommands" part="StrategyCommands.frame" class="hud bare" aria-label={t("strategy.commands.name")}>
  {#each commands as c (c.id)}
    {#if c.id == focused && c.name}
    <div id="Info" part="StrategyCommands.info" role="tooltip">
      <div class="info-head"><span part="StrategyCommands.title" class="info-title">{c.name}</span>{#if c.key}<span part="StrategyCommands.key" class="info-key">{c.key}</span>{/if}</div>
      {#if c.detail}<span part="StrategyCommands.detail" class="info-detail">{c.detail}</span>{/if}
      {#if c.cost || c.cooldownText || c.readyText}<div class="info-tags">
        {#if c.cost}<div part="StrategyCommands.price" class="price" data-affordable={c.affordable}>{#if c.costIcon}<img class="price-art" src={c.costIcon} alt="">{/if}<span class="price-figure">{c.cost}</span></div>{/if}
        {#if c.cooldownText}<span part="StrategyCommands.tag" class="tag">{c.cooldownText}</span>{/if}
        {#if c.readyText}<span part="StrategyCommands.tag" class="tag" data-ready="true">{c.readyText}</span>{/if}
      </div>{/if}
      {#if c.reason}<span part="StrategyCommands.detail" class="info-reason" role="status">{c.reason}</span>{/if}
    </div>
    {/if}
  {/each}
  <div id="Grid" part="StrategyCommands.grid" role="toolbar" aria-label={t("strategy.commands.name")}>
    {#each commands as c (c.id)}
      {#if !c.name}<div part="StrategyCommands.blank" class="blank"></div>{:else}
      <button part="StrategyCommands.command" class="command" aria-label={c.name} aria-description={c.reason ? c.reason : (c.readyText ? c.readyText : c.detail)} aria-pressed={c.active} disabled={!c.enabled || !c.affordable} data-active={c.active} data-cooling={c.cooldown > 0} data-affordable={c.affordable} data-enabled={c.enabled} onclick={command}><div class="face">
        {#if c.icon}<img part="StrategyCommands.art" class="art" src={c.icon} alt="">{:else}<div part="StrategyCommands.art" class="blank-art"><og-icon class="glyph" icon={c.glyph}></og-icon></div>{/if}
        {#if c.cooldown > 0}<div part="StrategyCommands.sweep" class="sweep" style:--left={c.cooldown >= 1 ? 1 : c.cooldown}></div>{/if}
        {#if c.cooldown > 0 && c.time}<span part="StrategyCommands.time" class="time">{c.time}</span>{/if}
        {#if c.action || c.key}<kbd part="StrategyCommands.key" class="key" data-action={c.action}>{c.key}</kbd>{/if}
        {#if !c.affordable && c.cost}<span part="StrategyCommands.cost" class="cost">{c.cost}</span>{/if}
      </div></button>
      {/if}
    {/each}
  </div>
</section>

<style>
:host { --cell: calc(var(--size-xl) * 0.8); --gap: calc(4 * var(--font-step-px)); display: flex; flex-direction: column; align-items: stretch; row-gap: calc(8 * var(--font-step-px)); inline-size: fit-content; max-inline-size: stretch; min-inline-size: 0; color: var(--hud-ink); }
/* The info card: smoked glass with an edge lit in the accent, as wide as
   the grid under it. */
#Info { display: flex; flex-direction: column; row-gap: calc(4 * var(--font-step-px)); inline-size: calc(var(--cell) * 4 + var(--gap) * 3 + 20 * var(--font-step-px)); max-inline-size: stretch; min-inline-size: 0; box-sizing: border-box; padding: calc(8 * var(--font-step-px)) calc(12 * var(--font-step-px)); background: var(--hud-plate-fill); box-shadow: var(--hud-plate-lit-rim); clip-path: polygon(var(--hud-plate-cut) 0, 100% 0, 100% calc(100% - var(--hud-plate-cut)), calc(100% - var(--hud-plate-cut)) 100%, 0 100%, 0 var(--hud-plate-cut)); }
.info-head { display: flex; align-items: center; justify-content: space-between; column-gap: calc(8 * var(--font-step-px)); min-inline-size: 0; }
.info-title { flex: 0 1 auto; min-inline-size: 0; font-size: var(--hud-size-name); font-weight: var(--hud-figure-weight); white-space: nowrap; text-overflow: -og-scroll var(--motion-duration-orbit) var(--motion-duration-turn); overflow: hidden; }
.info-key { flex: 0 1 auto; min-inline-size: calc(20 * var(--font-step-px)); max-inline-size: 40%; padding: 0 calc(5 * var(--font-step-px)); font-size: var(--hud-tag-size); line-height: 1.5; font-weight: var(--hud-figure-weight); text-align: center; color: var(--hud-key-ink); background: var(--hud-key-fill); border-radius: var(--hud-key-radius); box-shadow: var(--hud-key-shadow); white-space: nowrap; text-overflow: -og-scroll var(--motion-duration-orbit) var(--motion-duration-turn); overflow: hidden; }
/* What it does wraps: it is the card's body. */
.info-detail { font-size: var(--hud-size-xs); line-height: 1.35; color: var(--hud-ink-dim); white-space: normal; overflow-wrap: anywhere; }
.info-reason { font-size: var(--hud-size-xs); line-height: 1.35; font-weight: var(--hud-label-weight); color: var(--hud-harm); white-space: normal; overflow-wrap: anywhere; }
.info-tags { display: flex; flex-wrap: wrap; align-items: center; column-gap: calc(8 * var(--font-step-px)); row-gap: calc(4 * var(--font-step-px)); min-inline-size: 0; }
.price { display: flex; align-items: center; column-gap: calc(4 * var(--font-step-px)); flex: none; }
.price-art { flex: none; inline-size: var(--size-xs); block-size: var(--size-xs); object-fit: cover; }
.price-figure { font-size: var(--hud-size-sm); font-weight: var(--hud-figure-weight); font-stretch: var(--hud-figure-stretch); font-variant-numeric: var(--hud-figure-numeric); white-space: nowrap; }
.price[data-affordable=false] .price-figure { color: var(--hud-harm); }
.tag { flex: 0 1 auto; min-inline-size: 0; padding: 0 calc(6 * var(--font-step-px)); font-size: var(--hud-tag-size); line-height: 1.5; font-weight: var(--hud-figure-weight); font-stretch: var(--hud-figure-stretch); white-space: nowrap; text-overflow: -og-scroll var(--motion-duration-orbit) var(--motion-duration-turn); overflow: hidden; background: var(--hud-tag-fill); box-shadow: var(--hud-tag-rim); clip-path: polygon(var(--hud-tag-cut) 0, 100% 0, 100% calc(100% - var(--hud-tag-cut)), calc(100% - var(--hud-tag-cut)) 100%, 0 100%, 0 var(--hud-tag-cut)); }
.tag[data-ready=true] { color: var(--hud-gold); }
/* The grid on a glass plate: four tiles to a row. */
#Grid { display: grid; grid-template-columns: repeat(4, var(--cell)); grid-auto-rows: var(--cell); gap: var(--gap); justify-content: start; align-self: flex-end; padding: calc(10 * var(--font-step-px)); background: var(--hud-plate-fill); box-shadow: var(--hud-plate-rim); clip-path: polygon(var(--hud-plate-cut) 0, 100% 0, 100% calc(100% - var(--hud-plate-cut)), calc(100% - var(--hud-plate-cut)) 100%, 0 100%, 0 var(--hud-plate-cut)); }
.blank { background: var(--hud-slot-empty); clip-path: polygon(var(--hud-plate-cut) 0, 100% 0, 100% calc(100% - var(--hud-plate-cut)), calc(100% - var(--hud-plate-cut)) 100%, 0 100%, 0 var(--hud-plate-cut)); }
/* A tile: its fill is its lit edge, the art inset inside; the tiles are
   art and keep their size at any text scale. */
.command { inline-size: var(--cell); block-size: var(--cell); min-inline-size: 0; color: var(--hud-ink); }
.command::part(base) { padding: calc(2 * var(--font-step-px)); border: 0; border-radius: 0; background: var(--hud-edge); box-shadow: none; clip-path: polygon(var(--hud-plate-cut) 0, 100% 0, 100% calc(100% - var(--hud-plate-cut)), calc(100% - var(--hud-plate-cut)) 100%, 0 100%, 0 var(--hud-plate-cut)); }
.command[data-active=true]::part(base) { background: var(--hud-ready-edge); }
.command:disabled::part(base) { background: var(--hud-edge); }
.face { container-type: size; position: relative; inline-size: stretch; block-size: stretch; overflow: hidden; clip-path: polygon(var(--hud-plate-cut) 0, 100% 0, 100% calc(100% - var(--hud-plate-cut)), calc(100% - var(--hud-plate-cut)) 100%, 0 100%, 0 var(--hud-plate-cut)); }
.art { position: absolute; left: 0; top: 0; inline-size: 100%; block-size: 100%; object-fit: cover; }
.blank-art { position: absolute; left: 0; top: 0; inline-size: 100%; block-size: 100%; display: flex; align-items: center; justify-content: center; background: var(--hud-plate-fill); }
.glyph { inline-size: 55%; block-size: 55%; color: var(--hud-glyph); filter: var(--hud-glyph-shadow); }
.command:disabled .art { filter: var(--hud-unready); }
/* The cooldown still to run is dark; it turns clockwise from the top. */
.sweep { position: absolute; left: 0; top: 0; inline-size: 100%; block-size: 100%; background: var(--hud-sweep); mask-image: conic-gradient(transparent calc((1 - var(--left)) * 360deg), #000 0); }
.time { position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); text-align: center; font-size: var(--hud-size-cooldown); line-height: 1; font-weight: var(--hud-figure-weight); font-stretch: var(--hud-figure-stretch); font-variant-numeric: var(--hud-figure-numeric); white-space: nowrap; color: var(--hud-ink); text-shadow: var(--hud-shadow); -webkit-text-stroke-width: var(--hud-stroke-width); -webkit-text-stroke-color: var(--hud-stroke-color); paint-order: stroke fill; }
/* The hotkey in the top corner, stroked to stand on any art; its box is
   one line of its size, so the cap keeps to the corner, clear of the
   cooldown figure in the middle. */
.key { position: absolute; min-block-size: 0; block-size: calc(var(--hud-size-keycap) * 1.2); padding: 0; background: var(--hud-bare-fill); box-shadow: none; left: calc(4 * var(--font-step-px)); top: calc(2 * var(--font-step-px)); max-inline-size: calc(100% - 8 * var(--font-step-px)); font-family: inherit; font-size: var(--hud-size-keycap); line-height: 1.2; font-weight: var(--hud-figure-weight); color: var(--hud-ink); white-space: nowrap; text-overflow: -og-scroll var(--motion-duration-orbit) var(--motion-duration-turn); overflow: hidden; -webkit-text-stroke-width: var(--hud-stroke-width); -webkit-text-stroke-color: var(--hud-stroke-color); paint-order: stroke fill; }
/* The price it cannot pay, on a red tag in the bottom corner. */
.cost { position: absolute; right: calc(3 * var(--font-step-px)); bottom: calc(3 * var(--font-step-px)); max-inline-size: calc(100% - 6 * var(--font-step-px)); padding: 0 calc(4 * var(--font-step-px)); font-size: var(--hud-size-reason); line-height: 1.35; font-weight: var(--hud-figure-weight); font-stretch: var(--hud-figure-stretch); font-variant-numeric: var(--hud-figure-numeric); white-space: nowrap; text-overflow: -og-scroll var(--motion-duration-orbit) var(--motion-duration-turn); overflow: hidden; color: var(--hud-harm); background: var(--hud-tag-fill); box-shadow: var(--hud-tag-rim); clip-path: polygon(var(--hud-tag-cut) 0, 100% 0, 100% calc(100% - var(--hud-tag-cut)), calc(100% - var(--hud-tag-cut)) 100%, 0 100%, 0 var(--hud-tag-cut)); }
/* Under a touch screen the tiles are the controls: no key caps. */
@media (pointer: coarse) { .key, .info-key { display: none; } }
/* On a phone the grid takes the screen's width at the foot, eight tiles
   to a row, and no info card stands over it. */
@media (width < 600px) {
  :host { inline-size: stretch; --cell: calc(var(--size-lg) * 0.82); --gap: calc(3 * var(--font-step-px)); }
  #Info { display: none; }
  #Grid { grid-template-columns: repeat(8, var(--cell)); justify-content: space-between; align-self: stretch; padding: calc(5 * var(--font-step-px)); }
}
</style>
